import io
from boltons.jsonutils import JSONLIterator

def test_rel_seek_one():
    f = io.StringIO('{"1": 1}\n{"2": 2}\n')
    try:
        JSONLIterator(f, rel_seek=1.0)
        print("Success: rel_seek=1.0 accepted")
    except ValueError as e:
        print(f"Failure: rel_seek=1.0 rejected with {e}")

def test_rel_seek_one_reverse():
    f = io.StringIO('{"1": 1}\n{"2": 2}\n')
    try:
        JSONLIterator(f, reverse=True, rel_seek=1.0)
        print("Success: rel_seek=1.0 accepted with reverse=True")
    except ValueError as e:
        print(f"Failure: rel_seek=1.0 rejected with reverse=True and {e}")

if __name__ == "__main__":
    test_rel_seek_one()
    test_rel_seek_one_reverse()

